edits.before:
  // Watch for theme changes on ancestor elements (for live theme switching)
  this._setupThemeObserver()

  this._setupDismiss()

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.after:
  // Watch for theme changes on ancestor elements (for live theme switching)
  this._setupThemeObserver()

  this._setupDismiss()

  // Handle Tab key in capture phase to hide datepicker and allow focus to move
  this._onTabKey = (event: KeyboardEvent) => {
    if (event.key === 'Tab' && this._isShown) {
      this.hide()
      event.stopImmediatePropagation()
    }
  }
  this._element.addEventListener('keydown', this._onTabKey, true)

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.before:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

if (this._calendar) {
  this._calendar.destroy()
}

this._calendar = null
super.dispose()

edits.after:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

if (this._onTabKey) {
  this._element.removeEventListener('keydown', this._onTabKey, true)
}

if (this._calendar) {
  this._calendar.destroy()
}

this._calendar = null
super.dispose()
